import subprocess, os
EXE="/workspace/executable"
def run(*a, cwd="/workspace"):
    import subprocess
    r=subprocess.run([EXE]+list(a), capture_output=True, text=True, cwd=cwd)
    return r
def strip(s):
    return s.replace("\x1b[32m","").replace("\x1b[39m","").replace("\x1b[36m","")
for fmt in ["bytes","gb","gib","mb","mib"]:
    for sz in [0,1024,1500000,1073741824,5368709120,10485760]:
        p=f"/tmp/x{sz}"
        os.system(f"truncate -s {sz} {p} 2>/dev/null")
        r=run("-f",fmt,"-A",p)
        raw=strip(r.stdout)
        idx=raw.index(p)
        size_part=raw[:idx-1]
        print(f"fmt={fmt} sz={sz} size_part={repr(size_part)} len={len(size_part)}")
    print("---")
PY"}

