#[derive(Debug, Clone, PartialEq)]
enum Format {
    Metric,
    Binary,
    Bytes,
    Gb,
    Gib,
    Mb,
    Mib,
}

impl Format {
    fn from_str(s: &str) -> Option<Format> {
        match s {
            "metric" => Some(Format::Metric),
            "binary" => Some(Format::Binary),
            "bytes" => Some(Format::Bytes),
            "gb" => Some(Format::Gb),
            "gib" => Some(Format::Gib),
            "mb" => Some(Format::Mb),
            "mib" => Some(Format::Mib),
            _ => None,
        }
    }
    fn debug_name(&self) -> &'static str {
        match self {
            Format::Metric => "Metric",
            Format::Binary => "Binary",
            Format::Bytes => "Bytes",
            Format::Gb => "GB",
            Format::Gib => "Gib",
            Format::Mb => "MB",
            Format::Mib => "Mib",
        }
    }
}

fn format_size(bytes: u64, fmt: &Format) -> String {
    match fmt {
        Format::Binary => {
            if bytes <= 1024 {
                format!("{:>7}   B", bytes)
            } else if bytes <= 1024*1024 {
                format!("{:>7.2} KiB", bytes as f64 / 1024.0)
            } else if bytes <= 1024*1024*1024 {
                format!("{:>7.2} MiB", bytes as f64 / (1024.0*1024.0))
            } else {
                format!("{:>7.2} GiB", bytes as f64 / (1024.0*1024.0*1024.0))
            }
        }
        Format::Metric => {
            if bytes <= 1000 {
                format!("{:>7}  B", bytes)
            } else if bytes <= 1_000_000 {
