        log_file: Option<String>,
        stats: bool,
        no_sort: bool,
        no_total: bool,
        input: Vec<String>,
    },
    InteractiveWithGlobals {
        threads: u64,
        format: Format,
        apparent: bool,
        count_hard: bool,
        stay: bool,
        ignore: Vec<String>,
        log_file: Option<String>,
        no_entry_check: bool,
        input: Vec<String>,
    },
}

fn basename_of(argv0: &str) -> String {
    // basename: after last '/'
    match argv0.rfind('/') {
        Some(i) => argv0[i+1..].to_string(),
        None => argv0.to_string(),
    }
}

fn is_known_top_long(name: &str) -> bool {
    matches!(name, "threads" | "format" | "apparent-size" | "count-hard-links" | "stay-on-filesystem" | "ignore-dirs" | "log-file" | "help" | "version")
}

fn is_known_top_short(c: char) -> bool {
    matches!(c, 't' | 'f' | 'A' | 'l' | 'x' | 'i' | 'h' | 'V')
}

fn next_arg_looks_like_known_flag(s: &str) -> bool {
    if s == "-" || s == "--" {
        return false;
    }
    if s.starts_with("--") {
        let name = if let Some(eq) = s.find('=') { &s[2..eq] } else { &s[2..] };
        // empty after --? e.g., "--"? already handled. "--=?" treat as unknown
        if name.is_empty() { return false; }
        return is_known_top_long(name);
    } else if s.starts_with('-') && s.len() > 1 {
        // combined shorts: check first char
        let c = s.chars().nth(1).unwrap();
        return is_known_top_short(c);
    }
    false
}

