// Error helpers
fn err_unexpected(arg: &str, bin_usage: &str) -> String {
    // bin_usage is e.g., "dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]..." or "executable aggregate [OPTIONS] [INPUT]..." etc.
    // For top-level, bin is always "dua", for subcommands, bin is actual bin name + subcommand
    let tip_arg = if arg.starts_with("--") {
        format!("-- {}", arg)
    } else if arg.starts_with('-') {
        format!("-- {}", arg)
    } else {
        // positional extra for completions? No tip
        String::new()
    };
    if tip_arg.is_empty() {
        format!("error: unexpected argument '{}' found\n\nUsage: {}\n\nFor more information, try '--help'.\n", arg, bin_usage)
    } else {
        // tip: to pass '<arg>' as a value, use '<tip_arg>'
        // tip_arg is like "-- --unknown" or "-- -Z"
        // Actually format is: use '-- --unknown' (with quotes)
        format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '{}'\n\nUsage: {}\n\nFor more information, try '--help'.\n", arg, arg, tip_arg, bin_usage)
    }
}

fn top_usage() -> String {
    "dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...".to_string()
}

fn agg_usage_generic(bin: &str) -> String {
    format!("{} aggregate [OPTIONS] [INPUT]...", bin)
}
fn int_usage_generic(bin: &str) -> String {
    format!("{} interactive [OPTIONS] [INPUT]...", bin)
}
fn comp_usage(bin: &str) -> String {
    format!("{} completions <SHELL>", bin)
}

