// ===== Display helpers =====
fn color_green(s: &str) -> String {
    format!("\x1b[32m{}\x1b[39m", s)
}
fn color_cyan(s: &str) -> String {
    format!("\x1b[36m{}\x1b[39m", s)
}

fn error_suffix(count: u64) -> String {
    if count == 0 {
        String::new()
    } else if count == 1 {
        "  <1 IO Error>".to_string()
    } else {
        format!("  <{} IO Errors>", count)
    }
}

// ===== Execution =====

fn execute_completions(shell: String) {
    let content = match shell.as_str() {
        "bash" => include_str!("../ref/bash.txt"),
        "zsh" => include_str!("../ref/zsh.txt"),
        "fish" => include_str!("../ref/fish.txt"),
        "elvish" => include_str!("../ref/elvish.txt"),
        "powershell" => include_str!("../ref/powershell.txt"),
        _ => unreachable!(),
    };
    use std::io::Write;
    let _ = std::io::stdout().write_all(content.as_bytes());
    std::process::exit(0);
}

fn is_interactive_tty() -> bool {
    // Check if stdout is a tty via isatty
    // Use libc isatty if available, else fallback to checking TERM?
    // We'll use std::os::unix::io::AsRawFd + libc::isatty via raw syscall?
    // Simplest: try to use `isatty` via calling `tty` command? Better to implement via rustix? No deps.
    // We'll implement by checking if /dev/stdout is a character device? Actually `std::fs::metadata("/dev/stdout")`?
    // Easiest: use unsafe call to libc isatty(1) via extern C without libc crate (use raw syscall).
    // On Linux, isatty can be checked via `nix`? We'll just try to open /dev/tty?
    // Alternative: check env var? No.
    // We'll implement via `std::os::unix::fs::FileTypeExt`? Not.
    // Simplest robust: use `unsafe { libc_isatty(1) }` by declaring extern.
    unsafe { isatty(1) == 1 }
