// Helper to get aggregated size for explicit input (file or dir) with symlink handling
// Returns (size, is_dir_for_color, errors)
fn size_for_input(input: &str, ctx: &mut TravCtx) -> (u64, bool, u64) {
    let p = Path::new(input);
    // lstat
    let lmeta = match std::fs::symlink_metadata(p) {
        Ok(m) => m,
        Err(_) => {
            // Check if path ends with '/' and parent exists? Still error (as observed for file with slash)
            return (0, true, 1);
        }
    };
    if lmeta.file_type().is_symlink() {
        // symlink explicit
        match std::fs::metadata(p) {
            Ok(t) => {
                if t.is_dir() {
                    // follow dir: need to traverse target contents
                    // For ignore check, use canonical of input (which resolves to target)
                    // Use traverse_path on canonical target? But to preserve stats correctly, traverse via input path (which follows)?
                    // Our traverse_path prunes top symlink, so we need special handling: traverse target via canonical path
                    // Get canonical target path
                    let canon = match std::fs::canonicalize(p) {
                        Ok(pb) => pb.to_string_lossy().to_string(),
                        Err(_) => input.to_string(),
                    };
                    // Check ignore for this dir (as root with check_ignore=true? For multiple inputs, check; for single, caller decides)
                    // Here we assume check_ignore=true (for multiple). For single expansion, caller will handle separately.
                    // To avoid duplicating logic, just call traverse_path on canon with check_ignore=true and root_dev=None
                    // But need to handle that canon may be same as another input's target (like linkdir vs real) - dedup for dirs? Dirs not deduped, files with nlink1 not deduped, so fine.
                    let sz = traverse_path(&canon, ctx, None, true);
                    (sz, true, 0)
                } else {
                    // symlink to file: use lstat size
                    let sz = if ctx.apparent { lmeta.size() } else { lmeta.blocks() * 512 };
                    ctx.record(sz);
                    (sz, false, 0)
                }
            }
            Err(_) => {
                // dangling
                return (0, true, 1);
            }
        }
    } else if lmeta.is_dir() {
        // regular dir
        let sz = traverse_path(input, ctx, None, true);
        (sz, true, 0)
    } else {
        // file
        let sz = traverse_path(input, ctx, None, false);
        (sz, false, 0)
    }
}

// For single dir expansion, list children and compute each
fn expand_single_dir(dir_path: &str, ctx: &mut TravCtx) -> Result<Vec<(String, u64, bool)>, String> {
    // dir_path may be symlink to dir (follow) or regular dir
    // Returns list of (basename, size, is_dir)
    // On read failure, return Err with os error string for hard error
    let p = Path::new(dir_path);
    // Determine actual dir to read: if symlink to dir, read via symlink path (follows)
    // Check lstat
    let lmeta = std::fs::symlink_metadata(p).map_err(|e| e.to_string())?;
    let is_link = lmeta.file_type().is_symlink();
    let target_is_dir = if is_link {
        match std::fs::metadata(p) {
            Ok(t) => t.is_dir(),
            Err(e) => return Err(e.to_string()),
        }
    } else {
        lmeta.is_dir()
    };
    if !target_is_dir {
        // Not a dir (should not happen for expand, caller ensures dir)
        return Err("not a dir".to_string());
    }
    let rd = std::fs::read_dir(p).map_err(|e| e.to_string())?;
    let mut res = Vec::new();
    for entry in rd {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let child_path = entry.path();
        let child_str = child_path.to_string_lossy().to_string();
        let basename = entry.file_name().to_string_lossy().to_string();
        // prune symlinks
        let cmeta = match std::fs::symlink_metadata(&child_path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if cmeta.file_type().is_symlink() {
            continue;
        }
        if cmeta.is_dir() {
            let sz = traverse_path(&child_str, ctx, None, true);
            res.push((basename, sz, true));
        } else {
            let sz = traverse_path(&child_str, ctx, None, false);
            res.push((basename, sz, false));
        }
    }
    Ok(res)
}

fn execute_aggregate_common(
    bin: String,
    threads: u64,
    format: Format,
    apparent: bool,
    count_hard: bool,
    stay: bool,
    ignore: Vec<String>,
    log_file: Option<String>,
    inputs: Vec<String>,
    stats: bool,
    no_sort: bool,
    no_total: bool,
    is_top: bool, // true for top-level (command None), false for aggregate subcommand
) {
    // Write log file
    if let Some(lf) = log_file.clone() {
        let cmd_str = if is_top {
            "None".to_string()
        } else {
            // Aggregate command debug
            let mut s = String::new();
            s.push_str("Some(\n        Aggregate {\n");
            s.push_str(&format!("            statistics: {},\n", if stats { "true" } else { "false" }));
            s.push_str(&format!("            no_sort: {},\n", if no_sort { "true" } else { "false" }));
            s.push_str(&format!("            no_total: {},\n", if no_total { "true" } else { "false" }));
            s.push_str("            input: [\n");
            for inp in &inputs {
                s.push_str(&format!("                \"{}\",\n", inp));
            }
            s.push_str("            ],\n        },\n    )");
            s
        };
        let top_inputs_for_log: Vec<String> = if is_top { inputs.clone() } else { Vec::new() };
        // For aggregate subcommand, top input is [], sub input is inputs. For top, command None, input is inputs.
        // Our format_log expects top input and command_str. For top, command None, input = inputs. For aggregate, command Some(...), input = [] (top) and sub input in command.
        // Actually log shows for top: command None, input ["/tmp/mix"], for aggregate: command Some(Aggregate{... input [...] }), input [].
        // So for is_top, top_inputs = inputs, cmd None. For aggregate, top_inputs = [], cmd Some with sub inputs.
        let log_content = if is_top {
            format_log(threads, &format, apparent, count_hard, stay, &ignore, &inputs, &Some(lf.clone()), "None".to_string())
        } else {
            format_log(threads, &format, apparent, count_hard, stay, &ignore, &[], &Some(lf.clone()), cmd_str)
        };
        write_log_file(&lf, log_content);
    }

    let mut ctx = TravCtx::new(apparent, count_hard, stay, &ignore);

    // Handle empty inputs => CWD expansion (single dir ".")
    if inputs.is_empty() {
        // List CWD entries as single expansion
        match expand_single_dir(".", &mut ctx) {
            Ok(mut entries) => {
                // entries are (basename, size, is_dir)
                // Sort/display
                if no_sort {
                    // alphabetical by basename
                    entries.sort_by(|a,b| a.0.cmp(&b.0));
                } else {
                    entries.sort_by(|a,b| a.1.cmp(&b.1).then(a.0.cmp(&b.0)));
                }
                // Display
                use std::io::Write;
                let mut out = std::io::stdout().lock();
                // For stats, need to print to stderr after?
                if entries.is_empty() {
                    // no output
                } else if entries.len() == 1 && no_total {
                    // single, no total anyway
                    let (name, sz, is_dir) = &entries[0];
                    let fs = format_size(*sz, &format);
                    let line = if *is_dir {
                        format!("{} {}\n", color_green(&fs), color_cyan(name))
                    } else {
                        format!("{} {}\n", color_green(&fs), name)
                    };
                    let _ = out.write_all(line.as_bytes());
                } else if entries.len() == 1 {
                    let (name, sz, is_dir) = &entries[0];
                    let fs = format_size(*sz, &format);
                    let line = if *is_dir {
                        format!("{} {}\n", color_green(&fs), color_cyan(name))
                    } else {
                        format!("{} {}\n", color_green(&fs), name)
                    };
                    let _ = out.write_all(line.as_bytes());
                } else {
                    for (name, sz, is_dir) in &entries {
                        let fs = format_size(*sz, &format);
                        let line = if *is_dir {
                            format!("{} {}\n", color_green(&fs), color_cyan(name))
                        } else {
                            format!("{} {}\n", color_green(&fs), name)
                        };
                        let _ = out.write_all(line.as_bytes());
                    }
                    if !no_total {
                        let total: u64 = entries.iter().map(|(_,s,_,)| *s).sum();
                        let fs = format_size(total, &format);
                        let line = format!("{} total\n", color_green(&fs));
                        let _ = out.write_all(line.as_bytes());
                    }
                }
                if stats {
                    let smallest = ctx.smallest.unwrap_or(0);
                    let e = format!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}\n", ctx.entries, smallest, ctx.largest);
                    let _ = std::io::stderr().write_all(e.as_bytes());
                }
                std::process::exit(0);
            }
            Err(e) => {
                // CWD read failure? Unlikely. Treat as hard error?
                // Check if permission denied
                if e.contains("Permission denied") || e.contains("os error 13") {
                    use std::io::Write;
                    let _ = std::io::stderr().write_all(b"Error: Permission denied (os error 13)\n");
                    std::process::exit(1);
                } else {
                    // No output? Just exit 0?
                    std::process::exit(0);
                }
            }
        }
        return;
    }

    if inputs.len() == 1 {
        let inp = inputs[0].clone();
        // Check lstat
        let p = Path::new(&inp);
        match std::fs::symlink_metadata(p) {
            Err(_) => {
                // Single error input (nonexistent, etc.)
                use std::io::Write;
                let out = std::io::stdout().lock();
                let mut o = out;
                let fs = format_size(0, &format);
                let line = format!("{} {} {}\n", color_green(&fs), color_cyan(&inp), " <1 IO Error>");
                // Actually original: "\x1b[32m      0   B\x1b[39m \x1b[36m/nonexistent\x1b[39m  <1 IO Error>\n"
                // That's green size, space, cyan name, two spaces + "<1 IO Error>"? Let's check: stripped was '      0   B /nonexistent  <1 IO Error>\n' -> size + space + name + two spaces + error? Actually size "      0   B" + " " + "/nonexistent" + "  <1 IO Error>" (two spaces before <). Our error_suffix gives "  <1 IO Error>" (two spaces). Good. And we have green size + space + cyan name + suffix + "\n". Good.
                let _ = o.write_all(line.as_bytes());
                drop(o);
                if stats {
                    let e = format!("Statistics {{ entries_traversed: 0, smallest_file_in_bytes: 0, largest_file_in_bytes: 0 }}\n");
                    let _ = std::io::stderr().write_all(e.as_bytes());
                }
                std::process::exit(1);
            }
            Ok(lmeta) => {
                if lmeta.file_type().is_symlink() {
                    // symlink explicit single
                    match std::fs::metadata(p) {
                        Err(_) => {
                            // dangling
                            use std::io::Write;
                            let mut o = std::io::stdout().lock();
