// Helper to get aggregated size for explicit input (file or dir) with symlink handling
// Returns (size, is_dir_for_color, errors)
fn size_for_input(input: &str, ctx: &mut TravCtx) -> (u64, bool, u64) {
    let p = Path::new(input);
    // lstat
    let lmeta = match std::fs::symlink_metadata(p) {
        Ok(m) => m,
        Err(_) => {
            // Check if path ends with '/' and parent exists? Still error (as observed for file with slash)
            return (0, true, 1);
        }
    };
    if lmeta.file_type().is_symlink() {
        // symlink explicit
        match std::fs::metadata(p) {
            Ok(t) => {
                if t.is_dir() {
                    // follow dir: need to traverse target contents
                    // For ignore check, use canonical of input (which resolves to target)
                    // Use traverse_path on canonical target? But to preserve stats correctly, traverse via input path (which follows)?
                    // Our traverse_path prunes top symlink, so we need special handling: traverse target via canonical path
                    // Get canonical target path
                    let canon = match std::fs::canonicalize(p) {
                        Ok(pb) => pb.to_string_lossy().to_string(),
                        Err(_) => input.to_string(),
                    };
                    // Check ignore for this dir (as root with check_ignore=true? For multiple inputs, check; for single, caller decides)
                    // Here we assume check_ignore=true (for multiple). For single expansion, caller will handle separately.
                    // To avoid duplicating logic, just call traverse_path on canon with check_ignore=true and root_dev=None
                    // But need to handle that canon may be same as another input's target (like linkdir vs real) - dedup for dirs? Dirs not deduped, files with nlink1 not deduped, so fine.
                    let sz = traverse_path(&canon, ctx, None, true);
                    (sz, true, 0)
                } else {
                    // symlink to file: use lstat size
                    let sz = if ctx.apparent { lmeta.size() } else { lmeta.blocks() * 512 };
                    ctx.record(sz);
                    (sz, false, 0)
                }
            }
            Err(_) => {
                // dangling
                return (0, true, 1);
            }
        }
    } else if lmeta.is_dir() {
        // regular dir
        let sz = traverse_path(input, ctx, None, true);
        (sz, true, 0)
    } else {
        // file
        let sz = traverse_path(input, ctx, None, false);
        (sz, false, 0)
    }
}

// For single dir expansion, list children and compute each
fn expand_single_dir(dir_path: &str, ctx: &mut TravCtx) -> Result<Vec<(String, u64, bool)>, String> {
    // dir_path may be symlink to dir (follow) or regular dir
    // Returns list of (basename, size, is_dir)
    // On read failure, return Err with os error string for hard error
    let p = Path::new(dir_path);
    // Determine actual dir to read: if symlink to dir, read via symlink path (follows)
    // Check lstat
    let lmeta = std::fs::symlink_metadata(p).map_err(|e| e.to_string())?;
    let is_link = lmeta.file_type().is_symlink();
    let target_is_dir = if is_link {
        match std::fs::metadata(p) {
            Ok(t) => t.is_dir(),
            Err(e) => return Err(e.to_string()),
        }
    } else {
        lmeta.is_dir()
    };
    if !target_is_dir {
        // Not a dir (should not happen for expand, caller ensures dir)
        return Err("not a dir".to_string());
    }
    let rd = std::fs::read_dir(p).map_err(|e| e.to_string())?;
    let mut res = Vec::new();
    for entry in rd {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let child_path = entry.path();
        let child_str = child_path.to_string_lossy().to_string();
        let basename = entry.file_name().to_string_lossy().to_string();
        // prune symlinks
        let cmeta = match std::fs::symlink_metadata(&child_path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if cmeta.file_type().is_symlink() {
            continue;
        }
        if cmeta.is_dir() {
            let sz = traverse_path(&child_str, ctx, None, true);
            res.push((basename, sz, true));
        } else {
            let sz = traverse_path(&child_str, ctx, None, false);
            res.push((basename, sz, false));
        }
    }
    Ok(res)
}

